mapper.update:
update `goods`
set name=#{name}
  , price =#{price}
  , type_id=#{typeId}
  , introduction= #{introduction}
  , inventory=#{inventory}
where id = #{id}

mapper.select:
select g.id, g.name, g.price, t.type_name as typeName, g.introduction, g.photo_url, g.inventory, g.create_time from goods as g left join goods_type as t on t.id = g.type_id where g.deleted = 0 and g.status = 1
and g.id not in
#{id}
order by rand() limit #{limit}
